python3 -c "
import json, unicodedata
def cyr(s): return any('CYRILLIC' in unicodedata.name(ch,'') for ch in s)
d=json.load(open('Hanahuac/Resources/sr-geo.json'))
print('top keys:', list(d.keys()) if isinstance(d,dict) else 'LIST len '+str(len(d)))
import sys
def walk(o):
    vals=[]
    if isinstance(o,dict):
        for k,v in o.items(): vals+=walk(v)
    elif isinstance(o,list):
        for v in o: vals+=walk(v)
    elif isinstance(o,str): vals.append(o)
    return vals
allv=walk(d)
strs=[v for v in allv if any(c.isalpha() for c in v)]
nocyr=[v for v in strs if not cyr(v)]
print('total string values:',len(strs),'non-Cyrillic alpha values:',len(nocyr), nocyr[:15])
"

